edits.from:
aggregate:
  expr: 'SUM(SRC.W)'
  between: {value: SEQ, lower: LO, upper: HI}

aggregate:
  key: [ID]
  derivations:
    D: {type: int, derivation: SRC.W}
    V: {type: int, derivation: K.W}
    T: {type: int, derivation: {greatest: {sources: [D, V]}}}
  expr: 'SUM(T)'

edits.to:
case:
  - when: SEQ > 0
    then:
      aggregate:
        key: [ID]
        derivations:
          D: {type: int, derivation: SRC.W}
          V: {type: int, derivation: K.W}
          T: {type: int, derivation: {greatest: {sources: [D, V]}}}
        expr: 'SUM(T)'
